function validate([nums1, nums2]) {
  for (const [name, nums] of [['nums1', nums1], ['nums2', nums2]]) {
    if (!Array.isArray(nums)) return `${name} must be a list of numbers.`;
    if (nums.length < 1 || nums.length > 1000) return `${name} needs 1 to 1000 values.`;
    if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return `Each value of ${name} is a whole number from 1 to 10^5.`;
  }
  return null;
}

