function generate(rand, size) {
  const large = size === 'large';
  const pick = k => Math.floor(rand() * k);
  // Numbers built from 2, 3 and 5 multiply into each other's squares often.
  const smooth = [];
  for (let a = 1; a <= 100000; a *= 2)
    for (let b = a; b <= 100000; b *= 3)
      for (let c = b; c <= 100000; c *= 5) smooth.push(c);
  const style = rand();
  let pool;
  if (style < 0.1) pool = [1];
  else if (style < 0.2) pool = [1, 2, 4];
  else if (style < 0.5) pool = smooth.filter(v => v <= (large ? 100000 : 40));
  else if (style < 0.8) pool = smooth;
  else pool = null;
  const value = () => pool ? pool[pick(pool.length)] : 1 + pick(large ? 100000 : 30);
  const make = () => Array.from({ length: large ? 1000 : 1 + pick(7) }, value);
  return [make(), make()];
}
